void USkeletalMeshComponent::UpdateRigidBodyScaling(ETeleportType TeleportType)
{
	if (bEnablePerPolyCollision)
	{
		return;
	}

	const FVector3f SceneRelativeScale = FVector3f(GetRelativeScale3D());

	// Physics does not support nonuniform scaling of the bodies.
	if (!SceneRelativeScale.IsUniform())
	{
		return;
	}

	// Scale didn't actually change - nothing to do.
	if ((PrevRootRigidBodyScale - SceneRelativeScale).IsNearlyZero())
	{
		return;
	}

	// The legacy code computes a per-frame change factor (SceneRelativeScale / PrevRootRigidBodyScale)
	// and applies it to every body. When the scale crosses zero that factor becomes 0 (going to zero) or
	// Inf/NaN (coming back from zero), and the NaN corrupts body scale/mass and joint transforms
	// irrecoverably. We therefore special-case the two zero crossings and only use the incremental factor
	// on the safe nonzero->nonzero path.
	const bool bGoingToZero = SceneRelativeScale.IsNearlyZero() && !PrevRootRigidBodyScale.IsNearlyZero();
	const bool bComingFromZero = PrevRootRigidBodyScale.IsNearlyZero() && !SceneRelativeScale.IsNearlyZero();

	if (bGoingToZero)
	{
		// NOTE: disabling physics here has two expected side effects for the scale-to-zero case: the
		// animation / post-process anim blueprint may take over and modify the body transforms while scaled
		// out, and a runtime SetAllBodiesSimulatePhysics(true) ragdoll returns in its physics-asset default state.
		SetAllBodiesSimulatePhysics(false);

	}
	else if (bComingFromZero)
	{
		// RecreatePhysicsState() re-instantiates the bodies from the current bone transforms, which already
		// carry the component's (target) world scale, so they come back at the correct scale. No post-creation
		// rescale is needed here.
		RecreatePhysicsState();
	}
	else
	{

}

void USkeletalMeshComponent::SetAllBodiesSimulatePhysics(bool bNewSimulate)
{
	for(int32 i=0; i<Bodies.Num(); i++)
	{
		Bodies[i]->SetInstanceSimulatePhysics(bNewSimulate, false, true);
	}

	SetRootBodyIndex(RootBodyData.BodyIndex);	//Update the root body data cache in case animation has moved root body relative to root joint

void FBodyInstance::UpdateInstanceSimulatePhysics()
{
	// In skeletal case, we need both our bone and skelcomponent flag to be true.
	// This might be 'and'ing us with ourself, but thats fine.
	const bool bUseSimulate = IsInstanceSimulatingPhysics();
	bool bInitialized = false;

	FPhysicsCommand::ExecuteWrite(GetPhysicsActor(), [&](const FPhysicsActorHandle& Actor)
	{
		bInitialized = true;
		FPhysicsInterface::SetIsKinematic_AssumesLocked(Actor, !bUseSimulate);
		FPhysicsInterface::SetCcdEnabled_AssumesLocked(Actor, bUseCCD);
		FPhysicsInterface::SetMACDEnabled_AssumesLocked(Actor, bUseMACD);

	bSimulatePhysics = bSimulate;
	if ( !bMaintainPhysicsBlending )
	{
		if (bSimulatePhysics)
		{
			PhysicsBlendWeight = 1.f;
		}
		else
		{
			PhysicsBlendWeight = 0.f;
		}
	}

	UpdateInstanceSimulatePhysics();
}

template<typename T>
inline bool TVector<T>::IsNearlyZero(T Tolerance) const
{
    return
        FMath::Abs(X)<=Tolerance
        &&	FMath::Abs(Y)<=Tolerance
        &&	FMath::Abs(Z)<=Tolerance;
}

template<typename T>
UE_FORCEINLINE_HINT bool TVector<T>::AllComponentsEqual(T Tolerance) const
{
    return FMath::Abs(X - Y) <= Tolerance && FMath::Abs(X - Z) <= Tolerance && FMath::Abs(Y - Z) <= Tolerance;
}

